# RFC 7009 token revocation (generated by maquina:oauth). Takes an access or
# a refresh token and revokes its row only for the client it was issued to.
# The answer is always an empty 200, so it says nothing about the token.
class Oauth::RevocationsController < ActionController::API
  before_action :no_store

  # POST /oauth/revoke
  def create
    client = OauthClient.find_by(client_id: params[:client_id])
    digest = AccessToken.digest(params[:token])
    token = AccessToken.where(token_digest: digest).or(AccessToken.where(refresh_token_digest: digest)).first if params[:token].present?

    if client && token && token.oauth_client == client && !token.revoked?
      token.revoke!
      Rails.logger.info "[OAUTH] Token revoked by #{client.client_id} for #{token.user.email_address}"
    end

    head :ok
  end
end
